    info,
    sellToken,
    buyToken: q.buyToken,
    sellAmount: q.sellAmount,
    from: q.from,
    ...q.receiver !== void 0 && { receiver: q.receiver },
    ...q.slippageBps !== void 0 && { slippageBps: q.slippageBps },
    ...q.rpc !== void 0 && { rpc: q.rpc },
